-- ════════════════════════════════════════════════════════════════════════════════════
-- Load the member extract: raw TSV → stg_extract (as text) → member (typed and cleaned)
-- Run after each new extract. Generated by tools/gen_sql.py (the INSERT lists every column it reads).
-- ════════════════════════════════════════════════════════════════════════════════════
USE ccl;

-- 1. Raw file into staging. Client needs local-infile enabled:
--      singlestore --local-infile -h <host> -u <user> -p ccl < 03_load.sql
--    (In production, a SingleStore PIPELINE from S3 / Azure Blob does the same.)
TRUNCATE TABLE stg_extract;
LOAD DATA LOCAL INFILE 'member_features.tsv'
  INTO TABLE stg_extract
  FIELDS TERMINATED BY '\t'
  LINES TERMINATED BY '\n'
  IGNORE 1 LINES;

-- 2. Typed member rows. The cleaning formulas, per column type:
--      number   CASE WHEN x REGEXP '^-?[0-9]+(\.[0-9]+)?$' THEN CAST(x AS DECIMAL) END      ('NULL', '', text → NULL)
--      date     CASE WHEN x REGEXP '^m/d/yyyy$' THEN STR_TO_DATE(x, '%m/%d/%Y') END
--      money    ' 7,268.55 ' → 7268.55 ; ' -   ' → 0
--      G0       BP 60–260 / 30–160, HbA1c 3–20, eGFR 1–200, UACR 0–5000, BMI 10–80; outside → NULL (999 placeholders, BP 1/1)
INSERT INTO member (member_id, gender, age, nationality, plan_name, excluded, persona, clinical_score, comorbid_complication_score, kidney_score, utilization_score, age_sex_score, total_risk_score, priority_clinical_review, cohort_t2d_l12m, cohort_htn_l12m, flag_ckd, flag_dyslipidemia_l12m, flag_obesity, flag_ischemic_heart_disease, flag_heart_failure, flag_stroke, flag_dm_neuropathy, flag_dm_retinopathy_l12m, flag_pad_l12m, flag_dm_foot_ulcer_l12m, flag_amputation, flag_dka_l12m, flag_dm_hypoglycaemia_l12m, flag_dm_hypoglycaemia_last90days, flag_no_glucagon_last12months, flag_active_insulin, flag_active_aceinhibitor, flag_active_arbinhibitor, last_hba1c_value, last_hba1c_date, last_hba1c_date2, last_systolicpressure_value, last_diastolicpressure_value, last_systolicpressure_date, last_egfr_value, last_egfr_date, last_uacr_value, last_uacr_date, last_measuredbmi_value, last_egfr_test_date, last_urine_albumin_date, last_lipid_panel_date, last_renal_panel_date, last_potassium_date, last_retinal_screen_date, last_ophthalmology_visit, last_foot_exam, last_podiatry_visit, last_dietitian_visit, last_diabeducator_visit, first_e11_date, first_htn_date, last_visit_date, last_ip_discharge_date, last_ed_visit_date, ed_visits_l12m, ip_admissions_l12m, pdc_any_t2d_noninsulin, pdc_any_htn, pdc_mra, pdc_thiazide, days_since_t2d_supply_ran_out, days_since_htn_supply_ran_out, l12m_payable_diaborhtnrelated, trig1_hba1c_above_target, trig2_htn_tx_review, trig3_hypoglycemia_tx, trig4_post_discharge_care, trig5_kidney_check, trig6_hba1c_due, trig7_renal_potassium_due, trig8_nutrition_due, trig9_medication_adherence, trig10_new_diagnosis, trig11_annual_labs_due, trig12_eyeexam_due, trig13_highriskfoot_monitor, language, has_t2d, has_htn)
SELECT   CASE WHEN TRIM(s.`mask_id`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`mask_id`) END AS member_id,
  CASE WHEN TRIM(s.`GENDER`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`GENDER`) END AS gender,
  CASE WHEN TRIM(s.`AGE`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`AGE`) AS DECIMAL(14,4)) END AS age,
  CASE WHEN TRIM(s.`NATIONALITY`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`NATIONALITY`) END AS nationality,
  CASE WHEN TRIM(s.`plan_name`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`plan_name`) END AS plan_name,
  CASE WHEN TRIM(s.`Exclusion`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Exclusion`) AS DECIMAL(14,4)) END AS excluded,
  CASE WHEN TRIM(s.`Persona`) IN ('', 'NULL', 'null', 'NaN') THEN NULL ELSE TRIM(s.`Persona`) END AS persona,
  CASE WHEN TRIM(s.`Clinical_score`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Clinical_score`) AS DECIMAL(14,4)) END AS clinical_score,
  CASE WHEN TRIM(s.`Comorbid_complication_score`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Comorbid_complication_score`) AS DECIMAL(14,4)) END AS comorbid_complication_score,
  CASE WHEN TRIM(s.`Kidney_score`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Kidney_score`) AS DECIMAL(14,4)) END AS kidney_score,
  CASE WHEN TRIM(s.`Utilization_score`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Utilization_score`) AS DECIMAL(14,4)) END AS utilization_score,
  CASE WHEN TRIM(s.`Age_sex_score`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Age_sex_score`) AS DECIMAL(14,4)) END AS age_sex_score,
  CASE WHEN TRIM(s.`Total_risk_Score`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Total_risk_Score`) AS DECIMAL(14,4)) END AS total_risk_score,
  CASE WHEN TRIM(s.`Priority_clinical_review`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Priority_clinical_review`) AS DECIMAL(14,4)) END AS priority_clinical_review,
  CASE WHEN TRIM(s.`cohort_t2d_l12m`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`cohort_t2d_l12m`) AS DECIMAL(14,4)) END AS cohort_t2d_l12m,
  CASE WHEN TRIM(s.`cohort_htn_l12m`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`cohort_htn_l12m`) AS DECIMAL(14,4)) END AS cohort_htn_l12m,
  CASE WHEN TRIM(s.`flag_ckd`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_ckd`) AS DECIMAL(14,4)) END AS flag_ckd,
  CASE WHEN TRIM(s.`flag_dyslipidemia_l12m`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_dyslipidemia_l12m`) AS DECIMAL(14,4)) END AS flag_dyslipidemia_l12m,
  CASE WHEN TRIM(s.`flag_obesity`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_obesity`) AS DECIMAL(14,4)) END AS flag_obesity,
  CASE WHEN TRIM(s.`flag_ischemic_heart_disease`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_ischemic_heart_disease`) AS DECIMAL(14,4)) END AS flag_ischemic_heart_disease,
  CASE WHEN TRIM(s.`flag_heart_failure`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_heart_failure`) AS DECIMAL(14,4)) END AS flag_heart_failure,
  CASE WHEN TRIM(s.`flag_stroke`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_stroke`) AS DECIMAL(14,4)) END AS flag_stroke,
  CASE WHEN TRIM(s.`flag_dm_neuropathy`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_dm_neuropathy`) AS DECIMAL(14,4)) END AS flag_dm_neuropathy,
  CASE WHEN TRIM(s.`flag_dm_retinopathy_l12m`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_dm_retinopathy_l12m`) AS DECIMAL(14,4)) END AS flag_dm_retinopathy_l12m,
  CASE WHEN TRIM(s.`flag_pad_l12m`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_pad_l12m`) AS DECIMAL(14,4)) END AS flag_pad_l12m,
  CASE WHEN TRIM(s.`flag_dm_foot_ulcer_l12m`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_dm_foot_ulcer_l12m`) AS DECIMAL(14,4)) END AS flag_dm_foot_ulcer_l12m,
  CASE WHEN TRIM(s.`flag_amputation`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_amputation`) AS DECIMAL(14,4)) END AS flag_amputation,
  CASE WHEN TRIM(s.`flag_dka_l12m`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_dka_l12m`) AS DECIMAL(14,4)) END AS flag_dka_l12m,
  CASE WHEN TRIM(s.`flag_dm_hypoglycaemia_l12m`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_dm_hypoglycaemia_l12m`) AS DECIMAL(14,4)) END AS flag_dm_hypoglycaemia_l12m,
  CASE WHEN TRIM(s.`flag_dm_hypoglycaemia_last90days`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_dm_hypoglycaemia_last90days`) AS DECIMAL(14,4)) END AS flag_dm_hypoglycaemia_last90days,
  CASE WHEN TRIM(s.`flag_no_glucagon_last12months`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_no_glucagon_last12months`) AS DECIMAL(14,4)) END AS flag_no_glucagon_last12months,
  CASE WHEN TRIM(s.`flag_active_insulin`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_active_insulin`) AS DECIMAL(14,4)) END AS flag_active_insulin,
  CASE WHEN TRIM(s.`flag_active_ACEinhibitor`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_active_ACEinhibitor`) AS DECIMAL(14,4)) END AS flag_active_aceinhibitor,
  CASE WHEN TRIM(s.`flag_active_ARBinhibitor`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`flag_active_ARBinhibitor`) AS DECIMAL(14,4)) END AS flag_active_arbinhibitor,
  CASE WHEN (CASE WHEN TRIM(s.`Last_HbA1c_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_HbA1c_Value`) AS DECIMAL(14,4)) END) BETWEEN 3 AND 20 THEN (CASE WHEN TRIM(s.`Last_HbA1c_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_HbA1c_Value`) AS DECIMAL(14,4)) END) END AS last_hba1c_value,
  CASE WHEN TRIM(s.`Last_HbA1c_Date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`Last_HbA1c_Date`), '%m/%d/%Y') END AS last_hba1c_date,
  CASE WHEN TRIM(s.`last_hba1c_date2`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_hba1c_date2`), '%m/%d/%Y') END AS last_hba1c_date2,
  CASE WHEN (CASE WHEN TRIM(s.`Last_SystolicPressure_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_SystolicPressure_Value`) AS DECIMAL(14,4)) END) BETWEEN 60 AND 260 THEN (CASE WHEN TRIM(s.`Last_SystolicPressure_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_SystolicPressure_Value`) AS DECIMAL(14,4)) END) END AS last_systolicpressure_value,
  CASE WHEN (CASE WHEN TRIM(s.`Last_DiastolicPressure_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_DiastolicPressure_Value`) AS DECIMAL(14,4)) END) BETWEEN 30 AND 160 THEN (CASE WHEN TRIM(s.`Last_DiastolicPressure_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_DiastolicPressure_Value`) AS DECIMAL(14,4)) END) END AS last_diastolicpressure_value,
  CASE WHEN TRIM(s.`Last_SystolicPressure_Date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`Last_SystolicPressure_Date`), '%m/%d/%Y') END AS last_systolicpressure_date,
  CASE WHEN (CASE WHEN TRIM(s.`Last_eGFR_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_eGFR_Value`) AS DECIMAL(14,4)) END) BETWEEN 1 AND 200 THEN (CASE WHEN TRIM(s.`Last_eGFR_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_eGFR_Value`) AS DECIMAL(14,4)) END) END AS last_egfr_value,
  CASE WHEN TRIM(s.`Last_eGFR_Date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`Last_eGFR_Date`), '%m/%d/%Y') END AS last_egfr_date,
  CASE WHEN (CASE WHEN TRIM(s.`Last_UACR_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_UACR_Value`) AS DECIMAL(14,4)) END) BETWEEN 0 AND 5000 THEN (CASE WHEN TRIM(s.`Last_UACR_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_UACR_Value`) AS DECIMAL(14,4)) END) END AS last_uacr_value,
  CASE WHEN TRIM(s.`Last_UACR_Date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`Last_UACR_Date`), '%m/%d/%Y') END AS last_uacr_date,
  CASE WHEN (CASE WHEN TRIM(s.`Last_MeasuredBMI_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_MeasuredBMI_Value`) AS DECIMAL(14,4)) END) BETWEEN 10 AND 80 THEN (CASE WHEN TRIM(s.`Last_MeasuredBMI_Value`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Last_MeasuredBMI_Value`) AS DECIMAL(14,4)) END) END AS last_measuredbmi_value,
  CASE WHEN TRIM(s.`last_egfr_test_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_egfr_test_date`), '%m/%d/%Y') END AS last_egfr_test_date,
  CASE WHEN TRIM(s.`last_urine_albumin_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_urine_albumin_date`), '%m/%d/%Y') END AS last_urine_albumin_date,
  CASE WHEN TRIM(s.`last_lipid_panel_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_lipid_panel_date`), '%m/%d/%Y') END AS last_lipid_panel_date,
  CASE WHEN TRIM(s.`last_renal_panel_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_renal_panel_date`), '%m/%d/%Y') END AS last_renal_panel_date,
  CASE WHEN TRIM(s.`last_potassium_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_potassium_date`), '%m/%d/%Y') END AS last_potassium_date,
  CASE WHEN TRIM(s.`last_retinal_screen_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_retinal_screen_date`), '%m/%d/%Y') END AS last_retinal_screen_date,
  CASE WHEN TRIM(s.`last_ophthalmology_visit`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_ophthalmology_visit`), '%m/%d/%Y') END AS last_ophthalmology_visit,
  CASE WHEN TRIM(s.`last_foot_exam`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_foot_exam`), '%m/%d/%Y') END AS last_foot_exam,
  CASE WHEN TRIM(s.`last_podiatry_visit`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_podiatry_visit`), '%m/%d/%Y') END AS last_podiatry_visit,
  CASE WHEN TRIM(s.`last_dietitian_visit`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_dietitian_visit`), '%m/%d/%Y') END AS last_dietitian_visit,
  CASE WHEN TRIM(s.`last_diabeducator_visit`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_diabeducator_visit`), '%m/%d/%Y') END AS last_diabeducator_visit,
  CASE WHEN TRIM(s.`first_e11_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`first_e11_date`), '%m/%d/%Y') END AS first_e11_date,
  CASE WHEN TRIM(s.`first_htn_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`first_htn_date`), '%m/%d/%Y') END AS first_htn_date,
  CASE WHEN TRIM(s.`last_visit_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_visit_date`), '%m/%d/%Y') END AS last_visit_date,
  CASE WHEN TRIM(s.`last_ip_discharge_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_ip_discharge_date`), '%m/%d/%Y') END AS last_ip_discharge_date,
  CASE WHEN TRIM(s.`last_ed_visit_date`) REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(s.`last_ed_visit_date`), '%m/%d/%Y') END AS last_ed_visit_date,
  CASE WHEN TRIM(s.`ed_visits_l12m`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`ed_visits_l12m`) AS DECIMAL(14,4)) END AS ed_visits_l12m,
  CASE WHEN TRIM(s.`ip_admissions_l12m`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`ip_admissions_l12m`) AS DECIMAL(14,4)) END AS ip_admissions_l12m,
  CASE WHEN TRIM(s.`pdc_any_t2d_noninsulin`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`pdc_any_t2d_noninsulin`) AS DECIMAL(14,4)) END AS pdc_any_t2d_noninsulin,
  CASE WHEN TRIM(s.`pdc_any_htn`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`pdc_any_htn`) AS DECIMAL(14,4)) END AS pdc_any_htn,
  CASE WHEN TRIM(s.`pdc_mra`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`pdc_mra`) AS DECIMAL(14,4)) END AS pdc_mra,
  CASE WHEN TRIM(s.`pdc_thiazide`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`pdc_thiazide`) AS DECIMAL(14,4)) END AS pdc_thiazide,
  CASE WHEN TRIM(s.`days_since_t2d_supply_ran_out`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`days_since_t2d_supply_ran_out`) AS DECIMAL(14,4)) END AS days_since_t2d_supply_ran_out,
  CASE WHEN TRIM(s.`days_since_htn_supply_ran_out`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`days_since_htn_supply_ran_out`) AS DECIMAL(14,4)) END AS days_since_htn_supply_ran_out,
  CASE WHEN TRIM(s.`l12m_payable_DiaborHTNrelated`) = '-' THEN 0 WHEN REPLACE(TRIM(s.`l12m_payable_DiaborHTNrelated`), ',', '') REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(REPLACE(TRIM(s.`l12m_payable_DiaborHTNrelated`), ',', '') AS DECIMAL(14,2)) END AS l12m_payable_diaborhtnrelated,
  CASE WHEN TRIM(s.`Trig1_HbA1c_above_target`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig1_HbA1c_above_target`) AS DECIMAL(14,4)) END AS trig1_hba1c_above_target,
  CASE WHEN TRIM(s.`Trig2_HTN_tx_review`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig2_HTN_tx_review`) AS DECIMAL(14,4)) END AS trig2_htn_tx_review,
  CASE WHEN TRIM(s.`Trig3_hypoglycemia_tx`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig3_hypoglycemia_tx`) AS DECIMAL(14,4)) END AS trig3_hypoglycemia_tx,
  CASE WHEN TRIM(s.`Trig4_post_discharge_care`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig4_post_discharge_care`) AS DECIMAL(14,4)) END AS trig4_post_discharge_care,
  CASE WHEN TRIM(s.`Trig5_Kidney_check`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig5_Kidney_check`) AS DECIMAL(14,4)) END AS trig5_kidney_check,
  CASE WHEN TRIM(s.`Trig6_HbA1c_due`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig6_HbA1c_due`) AS DECIMAL(14,4)) END AS trig6_hba1c_due,
  CASE WHEN TRIM(s.`Trig7_Renal_Potassium_due`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig7_Renal_Potassium_due`) AS DECIMAL(14,4)) END AS trig7_renal_potassium_due,
  CASE WHEN TRIM(s.`Trig8_nutrition_due`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig8_nutrition_due`) AS DECIMAL(14,4)) END AS trig8_nutrition_due,
  CASE WHEN TRIM(s.`Trig9_medication_adherence`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig9_medication_adherence`) AS DECIMAL(14,4)) END AS trig9_medication_adherence,
  CASE WHEN TRIM(s.`Trig10_new_diagnosis`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig10_new_diagnosis`) AS DECIMAL(14,4)) END AS trig10_new_diagnosis,
  CASE WHEN TRIM(s.`Trig11_annual_labs_due`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig11_annual_labs_due`) AS DECIMAL(14,4)) END AS trig11_annual_labs_due,
  CASE WHEN TRIM(s.`Trig12_eyeexam_due`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig12_eyeexam_due`) AS DECIMAL(14,4)) END AS trig12_eyeexam_due,
  CASE WHEN TRIM(s.`Trig13_highriskfoot_monitor`) REGEXP '^-?[0-9]+(\\.[0-9]+)?$' THEN CAST(TRIM(s.`Trig13_highriskfoot_monitor`) AS DECIMAL(14,4)) END AS trig13_highriskfoot_monitor,
  CASE WHEN UPPER(TRIM(s.`NATIONALITY`)) IN ('EMIRATI', 'EGYPTIAN', 'JORDANIAN', 'LEBANESE', 'MAURITANIAN', 'MOROCCAN', 'PALESTINIAN', 'SUDANESE', 'SYRIAN', 'IRAQI', 'YEMENI', 'OMANI', 'SAUDI', 'TUNISIAN', 'ALGERIAN', 'BAHRAINI', 'KUWAITI', 'QATARI', 'LIBYAN') THEN 'Arabic' ELSE 'English' END,
  CASE WHEN TRIM(s.`cohort_t2d_l12m`) = '1' THEN 1 ELSE 0 END,
  CASE WHEN TRIM(s.`cohort_htn_l12m`) = '1' THEN 1 ELSE 0 END
FROM stg_extract s
WHERE TRIM(s.`mask_id`) <> ''
