-- 3. What the cleaning removed (G0), for the data-quality report
SELECT TRIM(`mask_id`) AS member_id, 'Last_SystolicPressure_Value' AS column_name, `Last_SystolicPressure_Value` AS raw_value
FROM stg_extract WHERE TRIM(`Last_SystolicPressure_Value`) REGEXP '^[0-9.]+$' AND CAST(TRIM(`Last_SystolicPressure_Value`) AS DECIMAL(10,2)) NOT BETWEEN 60 AND 260
UNION ALL
SELECT TRIM(`mask_id`), 'Last_DiastolicPressure_Value', `Last_DiastolicPressure_Value`
FROM stg_extract WHERE TRIM(`Last_DiastolicPressure_Value`) REGEXP '^[0-9.]+$' AND CAST(TRIM(`Last_DiastolicPressure_Value`) AS DECIMAL(10,2)) NOT BETWEEN 30 AND 160
UNION ALL
SELECT TRIM(`mask_id`), 'Last_MeasuredBMI_Value', `Last_MeasuredBMI_Value`
FROM stg_extract WHERE TRIM(`Last_MeasuredBMI_Value`) REGEXP '^[0-9.]+$' AND CAST(TRIM(`Last_MeasuredBMI_Value`) AS DECIMAL(10,2)) NOT BETWEEN 10 AND 80;
